import {
  CanActivate,
  ExecutionContext,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';

import { PrismaService } from '../../database/prisma.service';
import type { AuthenticatedRequest } from '../interfaces/authenticated-request.interface';

// These claims are generated by our login/register/refresh services.
interface AccessTokenPayload {
  sub: string;
  sid: string;
}

@Injectable()
export class AccessTokenGuard implements CanActivate {
  constructor(
    private readonly jwtService: JwtService,
    private readonly prisma: PrismaService,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context
      .switchToHttp()
      .getRequest<AuthenticatedRequest>();

    // 1. Extract the Bearer token from the Authorization header.
    const authorization = request.headers.authorization;
    const match = authorization
      ? /^Bearer\s+(\S+)$/i.exec(authorization)
      : null;

    if (!match) {
      throw new UnauthorizedException();
    }

    const accessToken = match[1];

    // 2. Verify JWT signature and expiration.
    let payload: AccessTokenPayload;

    try {
      payload =
        await this.jwtService.verifyAsync<AccessTokenPayload>(
          accessToken,
        );
    } catch {
      throw new UnauthorizedException();
    }

    // 3. Ensure the required identity claims exist.
    if (
      typeof payload.sub !== 'string' ||
      !payload.sub ||
      typeof payload.sid !== 'string' ||
      !payload.sid
    ) {
      throw new UnauthorizedException();
    }

    // 4. Confirm that the associated session is still active.
    const activeSession = await this.prisma.authSession.findFirst({
      where: {
        id: payload.sid,
        userId: payload.sub,
        revokedAt: null,
        expiresAt: {
          gt: new Date(),
        },
      },
      select: {
        id: true,
      },
    });

    if (!activeSession) {
      throw new UnauthorizedException();
    }

    // 5. Attach trusted identity to the request.
    request.user = {
      userId: payload.sub,
      sessionId: payload.sid,
    };

    return true;
  }
}
